# Total items generated: 14 categories * 75 quotes = 1050 quotes!

quotes_list = []
counter = 1

for cat in categories:
    cat_name = cat["name"]
    for text, author in cat["quotes"]:
        quotes_list.append({
            "id": f"q{counter:04d}",
            "text": text,
            "category": cat_name,
            "author": author
        })
        counter += 1

print(f"Generated {len(quotes_list)} quotes across {len(categories)} categories.")

# Write to src/data/quotes.ts
output_code = """import { QuoteItem } from '../types';

export const QUOTES: QuoteItem[] = """ + json.dumps(quotes_list, ensure_ascii=False, indent=2) + ";\n"

with open("src/data/quotes.ts", "w", encoding="utf-8") as f:
    f.write(output_code)

print("Successfully written to src/data/quotes.ts")
